<?php
declare(strict_types=1); namespace App\Http\Requests\Classrooms; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class StoreClassroomRequest extends FormRequest { public function authorize():bool{return $this->user()->can('classrooms.create');} protected function prepareForValidation():void{$this->merge(['code'=>trim((string)$this->code),'name'=>filled($this->name)?trim((string)$this->name):null]);} public function rules():array{return ['academic_year_id'=>['required','exists:academic_years,id'],'grade_level_id'=>['required',Rule::exists('grade_levels','id')->where('is_active',true)],'code'=>['required','max:50',Rule::unique('classrooms')->where(fn($q)=>$q->where('academic_year_id',$this->academic_year_id)->where('grade_level_id',$this->grade_level_id))],'name'=>['nullable','max:150'],'capacity'=>['nullable','integer','between:1,100'],'room_name'=>['nullable','max:100'],'homeroom_personnel_id'=>['nullable','exists:personnel,id'],'notes'=>['nullable','string'],'is_active'=>['boolean']];} public function messages():array{return ['academic_year_id.required'=>'Tahun ajaran wajib dipilih.','grade_level_id.required'=>'Tingkat kelas wajib dipilih.','code.required'=>'Kode rombel wajib diisi.','code.unique'=>'Kode rombel sudah digunakan pada tingkat dan tahun ajaran ini.'];}}
